// Shared by the read chunk and the edit chunk, so it must import nothing from
// `ui/edit/`, `stores/edit.ts` or `model/edit.js`: one such import pulls the
// whole edit layer into the read entry, and the guard only catches direct
// references to the mutation core.
import { Show, createSignal } from 'solid-js';
import type { JSX } from 'solid-js';
import { view } from '../../stores/view.js';

export type FieldKind = 'tekst' | 'datum' | 'iri';

const DCT = 'http://purl.org/dc/terms/';
const ODRL = 'http://www.w3.org/ns/odrl/2/';
const RDFS = 'http://www.w3.org/2000/01/rdf-schema#';
const SKOS = 'http://www.w3.org/2004/02/skos/core#';

export const PRED = {
  TITLE: [DCT + 'title', RDFS + 'label'],
  NAME: [RDFS + 'label', SKOS + 'prefLabel', DCT + 'title'],
  NOTE: [DCT + 'description', RDFS + 'comment'],
  ASSIGNER: [ODRL + 'assigner'],
  ASSIGNEE: [ODRL + 'assignee'],
  ISSUED: [DCT + 'issued'],
  IDENTIFIER: [DCT + 'identifier'],
} as const;

export interface FieldSpec {
  term: unknown;
  kind: FieldKind;
  preds: readonly string[];
  notApplicable?: string;
  value?: string | null;
  iri?: string | null;
  category?: string;
  hint?: string;
  newGroup?: boolean;
  multiline?: boolean;
  withoutPencil?: boolean;
  label?: string;
  focusKey?: string;
  variant?: 'actie' | 'knoopIri';
}

export interface CardHooks {
  field: (spec: FieldSpec, read: () => JSX.Element) => JSX.Element;
}

const [cardHooks, setCardHooks] = createSignal<CardHooks | null>(null);

const [sourceChoice, setSourceChoice] = createSignal(false);

export { sourceChoice, cardHooks, setSourceChoice, setCardHooks };

export function Field(props: { spec: FieldSpec; children?: JSX.Element }): JSX.Element {
  return (
    <Show when={view.editMode && cardHooks()} fallback={props.children}>
      {(h) => h().field(props.spec, () => props.children)}
    </Show>
  );
}
