export interface Constraint extends CardConstraint {
  term?: unknown;
  realises?: string[] | null;
  fulfils?: { iri: string }[];
}

export interface Coverage {
  status?: string;
  rule: { iri: string }[];
  conditions: Map<string, unknown>;
  uncovered?: string[];
  uncoveredReasons?: Record<string, string>;
  inConformsContext?: boolean;
  organisational?: boolean;
  via?: ViaLink[];
}

export interface ViaLink {
  constraint?: Constraint;
  artifacts: { iri: string }[];
  policies?: string[];
}

export interface CoverageRule {
  iri?: string | null;
  title?: string | null;
  label?: string | null;
  action?: { label?: string } | string | null;
  kind?: string;
  purposeConstraint?: Constraint | null;
  constraints?: Constraint[];
  refinements?: Constraint[];
  duties?: CoverageRule[];
  coverage?: Coverage | null;
  coveredBy?: { iri: string }[];
}

export interface CoveragePolicy {
  iri: string;
  anon?: boolean;
  title?: string | null;
  permissions?: CoverageRule[];
  prohibitions?: CoverageRule[];
  obligations?: CoverageRule[];
  inherited?: { title?: string; curie?: string; iri?: string; rules?: { type: string; rule: CoverageRule }[] }[];
}

export interface CoverageModel {
  sets: CoveragePolicy[];
  offers: CoveragePolicy[];
  agreements: CoveragePolicy[];
  artifacts?: { iri: string; title?: string | null }[];
  bundles?: { iri: string; title?: string | null }[];
}

export interface Entry {
  type: 'rule' | 'condition' | 'conforms';
  ref: string;
  kind: RuleKind;
  rule?: CoverageRule;
  constraint?: Constraint;
  nodeIri?: string | null;
  duties?: SetDuty[];
  scopes: { iri: string | null; title: string }[];
}

export interface Block { title: string | null; refs: string[]; notes?: Record<string, string> }

interface SetDuty { duty: CoverageRule; from: string | null }

export function ownConstraints(rule: CoverageRule): Constraint[] {
  return [
    ...(rule.purposeConstraint ? [rule.purposeConstraint] : []),
    ...(rule.constraints || []), ...(rule.refinements || []),
  ];
}

export function setDuties(pol: CoveragePolicy | null | undefined): SetDuty[] {
  if (!pol) return [];
  const out: SetDuty[] = (pol.obligations || []).map((duty) => ({ duty, from: null }));
  for (const g of pol.inherited || []) {
    for (const e of g.rules || []) {
      if (e.type !== 'obligation') continue;
      out.push({ duty: e.rule, from: g.title || g.curie || g.iri || null });
    }
  }
  return out;
}

function ruleKind(rule: CoverageRule, prohibition: boolean): RuleKind {
  if (prohibition) return 'verbod';
  return rule && rule.kind === 'duty' ? 'duty' : 'toestemming';
}

const allPolicies = (m: CoverageModel | null): CoveragePolicy[] =>
  (m ? [...m.offers, ...m.agreements, ...m.sets] : []);

export function buildFillIndex(m: CoverageModel | null): Map<string, Entry> {
  const ix = new Map<string, Entry>();
  if (!m) return ix;
  const add = (ref: string | null | undefined, desc: Entry) => {
    if (!ref) return;
    const cur = ix.get(ref);
    if (!cur) { ix.set(ref, desc); return; }
    for (const sc of desc.scopes) {
      if (!cur.scopes.some((x) => x.iri === sc.iri)) cur.scopes.push(sc);
    }
  };
  for (const pol of allPolicies(m)) {
    const scope = { iri: pol.anon ? null : pol.iri, title: pol.title || curie(pol.iri) };
    const duties = setDuties(pol);
    const loop = (rule: CoverageRule | null | undefined, kind: RuleKind, depth = 0): void => {
      if (!rule) return;
      add(rule.iri, { type: 'rule', ref: rule.iri!, rule, kind, scopes: [scope] });
      for (const c of ownConstraints(rule)) {
        if (!c) continue;
        if (c.technicalMeasure && c.rowRef) {
          add(c.rowRef, {
            type: 'conforms', ref: c.rowRef, constraint: c, rule, kind,
            nodeIri: c.conformsTo, duties, scopes: [scope],
          });
        } else if (c.iri) {
          add(c.iri, { type: 'condition', ref: c.iri, constraint: c, rule, kind, scopes: [scope] });
        }
      }
      if (depth < 3) for (const n of rule.duties || []) loop(n, 'duty', depth + 1);
    };
    for (const d of pol.obligations || []) loop(d, 'duty');
    for (const pm of pol.permissions || []) loop(pm, ruleKind(pm, false));
    for (const pb of pol.prohibitions || []) loop(pb, 'verbod');
  }
  return ix;
}

let lastModel: CoverageModel | null = null;
let lastIndex = new Map<string, Entry>();

export function fillIndex(): Map<string, Entry> {
  const m = model() as unknown as CoverageModel | null;
  if (m !== lastModel) { lastModel = m; lastIndex = buildFillIndex(m); }
  return lastIndex;
}

function policyTitle(iri: string | null | undefined, m: CoverageModel | null): string | null {
  if (!iri || !m) return null;
  const pol = allPolicies(m).find((x) => x.iri === iri);
  return (pol && pol.title) || curie(iri) || null;
}

export function isFulfilledBy(
  desc: Entry | null, scope: string | null, m: CoverageModel | null,
): Block[] {
  if (!desc) return [];
  if (desc.type === 'conforms') return [];
  if (desc.type === 'condition') {
    return [{
      title: null,
      refs: coverageNext(desc.constraint).map((x: any) => x.targetRef).filter(Boolean),
    }];
  }
  const all = coverageNext(desc.rule).filter((x: any) => x && x.targetRef);
  if (!all.length) return [];
  const own = scope ? all.filter((x: any) => (x.policies || []).includes(scope)) : [];
  if (own.length) return [{ title: null, refs: own.map((x: any) => x.targetRef) }];
  const perSet = new Map<string | null, string[]>();
  for (const x of all as any[]) {
    for (const pol of ((x.policies || []).length ? x.policies : [null]) as (string | null)[]) {
      const title = policyTitle(pol, m);
      if (!perSet.has(title)) perSet.set(title, []);
      const refs = perSet.get(title)!;
      if (!refs.includes(x.targetRef)) refs.push(x.targetRef);
    }
  }
  return [...perSet].map(([title, refs]) => ({ title, refs }));
}

function viaEntries(rule: CoverageRule | undefined, scope: string | null): ViaLink[] {
  const via = (rule && rule.coverage && rule.coverage.via) || [];
  if (!scope || !via.length) return via;
  const own = via.filter((v) => (v.policies || []).includes(scope));
  return own.length ? own : via;
}

function dutyOrigin(scope: string | null, m: CoverageModel | null): Map<string, string> {
  const map = new Map<string, string>();
  if (!scope || !m) return map;
  const pol = allPolicies(m).find((x) => x.iri === scope);
  for (const { duty, from } of setDuties(pol)) {
    if (duty && duty.iri && from) map.set(duty.iri, from);
  }
  return map;
}

function foldDuties(
  entries: SetDuty[] | undefined, nodeIri: string | null | undefined, scope: string | null,
): { duty: CoverageRule; from: string | null; direct: boolean; via: ViaLink[] }[] {
  const out = [];
  for (const { duty, from } of entries || []) {
    const direct = (duty.coveredBy || []).some((a) => a.iri === nodeIri);
    const via = viaEntries(duty, scope)
      .filter((v) => v.artifacts.some((a) => a.iri === nodeIri));
    if (!direct && !via.length) continue;
    out.push({ duty, from, direct, via: direct ? [] : via });
  }
  return out;
}

function constraintWord(c: Constraint | undefined): string | null {
  if (!c) return null;
  if (c.label) return c.label;
  const slot = c.slots && c.slots.left;
  return (slot && slot.text) || c.sentence || null;
}

function ruleSummary(rule: CoverageRule | undefined) {
  const cov = rule && rule.coverage;
  if (!cov) return null;
  const coveredSet = new Set(cov.conditions.keys());
  const uncoveredSet = new Set(cov.uncovered || []);
  const covered: Constraint[] = [];
  const uncovered: Constraint[] = [];
  const seen = new Set<string>();
  for (const c of ownConstraints(rule!)) {
    if (!c || !c.iri || seen.has(c.iri)) continue;
    if (coveredSet.has(c.iri)) { seen.add(c.iri); covered.push(c); }
    else if (uncoveredSet.has(c.iri)) { seen.add(c.iri); uncovered.push(c); }
  }
  return { cov, covered, uncovered };
}

export function fulfils(
  desc: Entry | null, scope: string | null, m: CoverageModel | null,
): Block[] {
  if (!desc) return [];
  if (desc.type === 'condition') {
    const refs = (desc.constraint!.fulfils || []).map((r) => r.iri).filter(Boolean);
    const origins = dutyOrigin(scope, m);
    const notes: Record<string, string> = {};
    for (const r of refs) if (origins.has(r)) notes[r] = text('cov.dutyFrom', { parent: origins.get(r) });
    return [{ title: null, refs, notes }];
  }
  if (desc.type !== 'conforms') return [];

  const refs: string[] = [];
  const sum = ruleSummary(desc.rule);
  const realises = desc.constraint && desc.constraint.realises;
  const mentions = (iri: string) => !realises || realises.includes(iri);
  if (sum && sum.cov.rule.length && desc.rule!.iri && mentions(desc.rule!.iri)) refs.push(desc.rule!.iri);
  if (sum) {
    for (const c of sum.covered) {
      if (c.iri && mentions(c.iri) && !refs.includes(c.iri)) refs.push(c.iri);
    }
  }
  const own = scope || (desc.scopes[0] || {}).iri || null;
  const blocks: Block[] = [{ title: null, refs }];
  const duties: string[] = [];
  const notes: Record<string, string> = {};
  for (const { duty, from, via, direct } of foldDuties(desc.duties, desc.nodeIri, own)) {
    if (!duty.iri || duties.includes(duty.iri)) continue;
    duties.push(duty.iri);
    const parts: string[] = [];
    if (from) parts.push(text('cov.dutyFrom', { parent: from }));
    if (!direct) {
      const names = [...new Set(via.map((v) => constraintWord(v.constraint)).filter(Boolean))];
      for (const name of names) parts.push(text('cov.dutyViaCond', { cond: name }));
      if (!names.length) parts.push(text('cov.dutyViaCondAnon'));
    }
    if (parts.length) notes[duty.iri] = parts.join(' · ');
  }
  if (duties.length) blocks.push({ title: text('fill.duties'), refs: duties, notes });
  return blocks;
}

export function notEnforced(
  desc: Entry | null,
): { uncovered: Constraint[]; reasons: Record<string, string> } | null {
  const rule = desc && (desc.type === 'rule' || desc.type === 'conforms') ? desc.rule : null;
  if (!rule) return null;
  const sum = ruleSummary(rule);
  if (!sum || !sum.uncovered.length) return null;
  return { uncovered: sum.uncovered, reasons: sum.cov.uncoveredReasons || {} };
}

export function ruleTitle(rule: CoverageRule | undefined, kind: RuleKind): string {
  if (!rule) return '';
  const act = rule.action;
  const actWord = (act && typeof act === 'object') ? act.label : act;
  return rule.title || rule.label || actWord
    || text(kind === 'duty' ? 'title.duty' : 'title.permission');
}

function coverageStatus(desc: Entry | undefined): 'full' | 'partial' {
  if (desc && desc.type === 'rule') {
    const cov = desc.rule && desc.rule.coverage;
    return cov && cov.status === 'partial' ? 'partial' : 'full';
  }
  return 'full';
}

const REF_HL = 'is-ref-hl';
const REF_BOX = 'is-ref-box';
const REF_PULSE = 'is-ref-pulse';
const HL_MS = 1800;

function searchRoot(): HTMLElement | null {
  if (typeof document === 'undefined') return null;
  return document.getElementById('app-hoofd') || document.body || null;
}

function refNodes(root: Element | null, attr: string, ref: string): HTMLElement[] {
  const out: HTMLElement[] = [];
  const loop = (n: Element) => {
    for (const c of Array.from(n.children || [])) {
      if (c.getAttribute && c.getAttribute(attr) === ref) out.push(c as HTMLElement);
      loop(c);
    }
  };
  if (root) loop(root);
  return out;
}

function refTargets(root: Element | null, ref: string): HTMLElement[] {
  const direct = refNodes(root, 'data-ref', ref);
  return direct.length ? direct : refNodes(root, 'data-art', ref);
}

function cardOfScope(scope: string | null): HTMLElement | null {
  const root = searchRoot();
  if (!root || !scope) return null;
  for (const n of refNodes(root, 'data-iri', scope)) {
    if (/\b(set-card|offer-group|agr-group)\b/.test(String(n.className || ''))) return n;
  }
  return null;
}

// A target inside a closed <details> cannot be highlighted itself; the outermost
// closed wrapper is marked instead.
function closedFoldSummary(node: Element | null): HTMLElement | null {
  const tag = (n: Element | null) => String((n && n.tagName) || '').toLowerCase();
  let box: HTMLElement | null = null;
  for (let cur: Element | null = node; cur && cur.parentElement; cur = cur.parentElement) {
    const p = cur.parentElement;
    if (tag(p) === 'details' && !(p as HTMLDetailsElement).open && tag(cur) !== 'summary') {
      box = p as HTMLElement;
    }
  }
  if (!box) return null;
  for (const c of Array.from(box.children)) if (tag(c) === 'summary') return c as HTMLElement;
  return box;
}

function anchorPosition(node: HTMLElement): 'in' | 'above' | 'below' {
  if (!node || typeof node.getBoundingClientRect !== 'function') return 'in';
  const r = node.getBoundingClientRect();
  const viewportHeight = (typeof window !== 'undefined' && window.innerHeight) || 0;
  if (!r || !viewportHeight) return 'in';
  if (!r.width && !r.height && !r.top && !r.bottom) return 'in';
  if (r.bottom <= 0) return 'above';
  if (r.top >= viewportHeight) return 'below';
  return 'in';
}

function visibleAnchor(ref: string, scope: string | null) {
  const root = searchRoot();
  if (!root || !ref) return null;
  const card = cardOfScope(scope);
  const own = card ? refTargets(card, ref) : [];
  const nodes = own.length ? own : refTargets(root, ref);
  if (!nodes.length) return null;
  const free = nodes.find((n) => !closedFoldSummary(n));
  const node = free || nodes[0];
  const box = free ? null : closedFoldSummary(node);
  const element = box || node;
  return { element, exact: !box, position: anchorPosition(element) };
}

let highlighted: HTMLElement[] = [];
const [edgeHint, setEdgeHint] = createSignal<'above' | 'below' | null>(null);

export function clearMarkers(): void {
  for (const n of highlighted) {
    if (n && n.classList) { n.classList.remove(REF_HL); n.classList.remove(REF_BOX); }
  }
  highlighted = [];
  setEdgeHint(null);
}

function mark(ref: string, on: boolean, scope: string | null): void {
  clearMarkers();
  if (!on) return;
  const anchor = visibleAnchor(ref, scope);
  if (!anchor) return;
  if (anchor.exact) {
    const root = cardOfScope(scope) || searchRoot();
    const inScope = refTargets(root, ref);
    const nodes = inScope.length ? inScope : refTargets(searchRoot(), ref);
    for (const n of nodes) {
      if (closedFoldSummary(n)) continue;
      n.classList.add(REF_HL);
      highlighted.push(n);
    }
  } else {
    anchor.element.classList.add(REF_HL);
    anchor.element.classList.add(REF_BOX);
    highlighted.push(anchor.element);
  }
  if (anchor.position !== 'in') setEdgeHint(anchor.position);
}

function mayAnimate(): boolean {
  return !(typeof window !== 'undefined' && typeof window.matchMedia === 'function'
    && window.matchMedia('(prefers-reduced-motion: reduce)').matches);
}

function openPathTo(target: HTMLElement): void {
  const path: HTMLElement[] = [];
  for (let cur: HTMLElement | null = target; cur; cur = cur.parentElement) path.push(cur);
  path.reverse();
  for (const n of path) {
    if (String(n.tagName || '').toLowerCase() !== 'details') continue;
    (n as HTMLDetailsElement).open = true;
    n.setAttribute('open', '');
  }
  for (const c of Array.from(target.children)) {
    if (c.classList && c.classList.contains('rij-fold')) {
      (c as HTMLDetailsElement).open = true;
      c.setAttribute('open', '');
    }
  }
}

function flash(node: HTMLElement, classes: string[]): void {
  for (const k of classes) node.classList.add(k);
  setTimeout(() => {
    if (!node.classList) return;
    for (const k of classes) node.classList.remove(k);
  }, HL_MS);
}

let jumpHook: ((ref: string, scope: string | null) => boolean | void) | null = null;

function jump(ref: string, scope: string | null): void {
  if (jumpHook) { jumpHook(ref, scope); return; }
  jumpToRef(ref, scope);
}

export function jumpToRef(ref: string, scope: string | null = null): boolean {
  clearMarkers();
  const card = cardOfScope(scope);
  const own = card ? refTargets(card, ref) : [];
  const target = own[0] || refTargets(searchRoot(), ref)[0];
  if (!target) return false;
  openPathTo(target);
  if (typeof target.scrollIntoView === 'function') {
    target.scrollIntoView({ behavior: mayAnimate() ? 'smooth' : 'auto', block: 'start' });
  }
  flash(target, [REF_HL, REF_PULSE]);
  return true;
}

interface PanelState { ref: string; scope: string | null }

const [panelState, setPanelState] = createSignal<PanelState | null>(null);

export const fillState = panelState;

let fromRect: DOMRect | null = null;

function rectOf(node: Element | null | undefined): DOMRect | null {
  if (!node || typeof node.getBoundingClientRect !== 'function') return null;
  try {
    const r = node.getBoundingClientRect();
    return r && (r.width || r.height) ? r : null;
  } catch { return null; }
}

export function openFill(
  ref: string, scope: string | null = null, options: { origins?: Element | null } = {},
): void {
  if (!ref) return;
  fromRect = rectOf(options.origins || null);
  clearMarkers();
  setPanelState({ ref, scope: scope || null });
}

export function closeFill(): void {
  fromRect = null;
  clearMarkers();
  setPanelState(null);
}

const [upOpen, setUpOpen] = createSignal(true);
const [downOpen, setDownOpen] = createSignal(true);

export function FillButton(props: {
  target: string; scope?: string | null; status?: 'full' | 'partial';
}): JSX.Element {
  const status = () => props.status ?? coverageStatus(fillIndex().get(props.target));
  const hint = () => text('fill.gearTitle');
  return (
    <Show when={props.target}>
      <button
        type="button"
        class={'rond-btn cov-gear cov-status ' + status()}
        title={hint()} aria-label={hint()}
        onClick={(e) => {
          e.preventDefault();
          e.stopPropagation();
          openFill(props.target, props.scope ?? null, { origins: e.currentTarget });
        }}
      >{'⚙'}</button>
    </Show>
  );
}

function RowContent(props: { desc: Entry }): JSX.Element {
  return (
    <Switch>
      <Match when={props.desc.type === 'rule'}>
        <RuleBadge kind={props.desc.kind} />
        <span class="op-name">{ruleTitle(props.desc.rule, props.desc.kind)}</span>
      </Match>
      <Match when={props.desc.type === 'condition'}>
        <ConstraintContent c={props.desc.constraint!} />
        <Show when={props.desc.constraint!.label}>
          <span class="c-note muted">{props.desc.constraint!.label}</span>
        </Show>
      </Match>
      <Match when={props.desc.type === 'conforms'}>
        <ConstraintContent c={props.desc.constraint!} />
      </Match>
    </Switch>
  );
}

const FLIP_MS = 200;
function flip(node: HTMLElement, origins: DOMRect | null): void {
  if (!node || !origins || !mayAnimate()) return;
  const to = rectOf(node);
  if (!to) return;
  const dx = origins.left - to.left;
  const dy = origins.top - to.top;
  if (!dx && !dy) return;
  node.style.transition = 'none';
  node.style.transform = `translate(${dx}px, ${dy}px)`;
  const release = () => {
    node.style.transition = `transform ${FLIP_MS}ms ease-out`;
    node.style.transform = 'translate(0, 0)';
    setTimeout(() => {
      if (!node.style) return;
      node.style.transition = '';
      node.style.transform = '';
    }, FLIP_MS + 60);
  };
  if (typeof requestAnimationFrame === 'function') {
    requestAnimationFrame(() => requestAnimationFrame(release));
  } else setTimeout(release, 16);
}

function Row(props: {
  target: string; scope: string | null; current?: boolean; note?: string | null;
}): JSX.Element {
  const desc = () => fillIndex().get(props.target);
  const exploreTarget = () => {
    const d = desc();
    if (!d) return null;
    if (d.type === 'rule') return (d.rule && (d.rule.iri || (d.rule as any).term)) || null;
    const c = d.constraint;
    return (c && (c.term || c.iri)) || null;
  };
  const title = () => {
    const c = desc()?.constraint;
    return [c && c.label, c && c.comment].filter(Boolean).join(' — ') || undefined;
  };
  return (
    <li
      class={'fill-row' + (props.current ? ' is-current' : '')}
      data-ref={props.target} tabindex="0" title={title()}
      ref={(el) => { if (props.current) flip(el, fromRect); }}
      onMouseEnter={() => mark(props.target, true, props.scope)}
      onMouseLeave={() => mark(props.target, false, props.scope)}
      onFocusIn={() => mark(props.target, true, props.scope)}
      onFocusOut={() => mark(props.target, false, props.scope)}
      onClick={(e) => {
        if (props.current || hitButton(e)) return;
        if ((e.detail || 1) > 1) return;
        e.preventDefault();
        jump(props.target, props.scope);
      }}
      onDblClick={(e) => {
        if (props.current || hitButton(e)) return;
        e.preventDefault();
        e.stopPropagation();
        openFill(props.target, props.scope, { origins: e.currentTarget });
      }}
    >
      <span class="fill-content">
        <Show
          when={desc()}
          fallback={<span class="muted">{curie(props.target) || props.target}</span>}
        >
          <RowContent desc={desc()!} />
        </Show>
        <Show when={props.note}>
          <span class="fill-note muted">{props.note}</span>
        </Show>
      </span>
      <Show when={desc()}>
        <span class="fill-acts">
          <Show when={!props.current}>
            <button
              type="button" class="fill-jump"
              title={text('fill.jump')} aria-label={text('fill.jump')}
              onClick={(e) => {
                e.preventDefault(); e.stopPropagation();
                jump(props.target, props.scope);
              }}
            >{'→'}</button>
          </Show>
          <Show when={!props.current}>
            <FillButton target={props.target} scope={props.scope} status={coverageStatus(desc())} />
          </Show>
        </span>
      </Show>
    </li>
  );
}

function hitButton(e: Event): boolean {
  for (let cur = e.target as Element | null; cur; cur = cur.parentElement) {
    if (String(cur.tagName || '').toLowerCase() === 'button') return true;
    if (String(cur.tagName || '').toLowerCase() === 'a') return true;
  }
  return false;
}

function BlockRows(props: {
  blocks: Block[]; scope: string | null; cls: string; closed?: boolean;
}): JSX.Element {
  return (
    <div class={'fill-block ' + props.cls} hidden={props.closed}>
      <For each={props.blocks}>{(b) => (
        <>
          <Show when={b.title}>
            <p class="fill-subhead muted">{b.title}</p>
          </Show>
          <ul class="clean fill-list">
            <For each={b.refs}>{(r) => (
              <Row target={r} scope={props.scope} note={(b.notes || {})[r] || null} />
            )}</For>
          </ul>
        </>
      )}</For>
    </div>
  );
}

function FoldEdge(props: {
  label: string; cls: string; open: () => boolean; set: (v: boolean) => void;
}): JSX.Element {
  const toggle = () => props.set(!props.open());
  return (
    <p
      class={'fill-edge ' + props.cls + ' is-foldable'}
      role="button" tabindex="0" aria-expanded={props.open()}
      onClick={toggle}
      onKeyDown={(e) => {
        if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); toggle(); }
      }}
    >{props.label}</p>
  );
}

export function FillPanel(props: {
  onJump?: (ref: string, scope: string | null) => boolean | void;
}): JSX.Element {
  const panel = () => panelState();
  const desc = () => {
    const s = panel();
    return s ? fillIndex().get(s.ref) : undefined;
  };
  const own = () => {
    const s = panel();
    return (s && s.scope) || (desc()?.scopes[0] || {}).iri || null;
  };
  const m = () => model() as unknown as CoverageModel | null;
  const up = createMemo(() => {
    void view.lang;
    return isFulfilledBy(desc() || null, own(), m()).filter((b) => b.refs.length);
  });
  const down = createMemo(() => {
    void view.lang;
    return fulfils(desc() || null, own(), m()).filter((b) => b.refs.length);
  });
  const uncovered = createMemo(() => notEnforced(desc() || null));
  const origins = () => (desc()?.scopes || []).map((sc) => sc.title).filter(Boolean);

  createEffect(() => {
    if (typeof document === 'undefined' || !document.body) return;
    document.body.classList[panel() ? 'add' : 'remove']('panel-open');
  });
  createEffect(() => { void panel(); clearMarkers(); });

  function onKey(e: KeyboardEvent): void {
    if (e.key !== 'Escape' || !panelState()) return;
    const a = typeof document !== 'undefined' ? document.activeElement : null;
    const tag = String((a && a.tagName) || '').toLowerCase();
    if (tag === 'input' || tag === 'textarea' || (a as HTMLElement | null)?.isContentEditable) return;
    closeFill();
    e.preventDefault();
    if (e.stopImmediatePropagation) e.stopImmediatePropagation();
    else e.stopPropagation();
  }
  if (typeof document !== 'undefined' && document.addEventListener) {
    document.addEventListener('keydown', onKey, true);
    onCleanup(() => {
      document.removeEventListener('keydown', onKey, true);
      document.body?.classList.remove('panel-open');
      clearMarkers();
    });
  }

  jumpHook = props.onJump || null;
  onCleanup(() => { jumpHook = null; });

  return (
    <>
      <Show when={panel()}>{(s) => (
        <aside class="insp-overlay" role="dialog" aria-label={text('fill.title')}>
          <div class="insp-head">
            <span class="insp-title">{text('fill.title')}</span>
            <button
              class="insp-close" type="button" title={text('panel.close')}
              onClick={() => closeFill()}
            >{'✕'}</button>
          </div>
          <div class="insp-body insp">
            <Show
              when={desc()}
              fallback={<p class="insp-none muted">{text('fill.unknown')}</p>}
            >
              <div class="fill">
                <Show when={up().length}>
                  <BlockRows
                    blocks={up()} scope={own()} cls="fill-up" closed={!upOpen()}
                  />
                </Show>
                <div class="fill-cur">
                  <Show when={up().length}>
                    <FoldEdge
                      label={text('fill.up')} cls="fill-edge-up"
                      open={upOpen} set={setUpOpen}
                    />
                  </Show>
                  <ul class="clean fill-list">
                    <Row target={s().ref} scope={own()} current />
                  </ul>
                  <Show when={origins().length}>
                    <p class="fill-origin muted">
                      {text('fill.origin', { sets: origins().join('; ') })}
                    </p>
                  </Show>
                  <Show when={down().length}>
                    <FoldEdge
                      label={text('fill.down')} cls="fill-edge-down"
                      open={downOpen} set={setDownOpen}
                    />
                  </Show>
                </div>
                <Show when={down().length}>
                  <BlockRows
                    blocks={down()} scope={own()} cls="fill-down" closed={!downOpen()}
                  />
                </Show>
                <Show when={uncovered()}>{(u) => (
                  <div class="fill-block fill-off">
                    <p class="fill-head">{text('cov.notEnforcedHead')}</p>
                    <ul class="clean cov-conds">
                      <For each={u().uncovered}>{(c) => (
                        <li
                          class={'cov-cond cov-cond-off muted'}
                          data-ref={c.iri} tabindex="0"
                          onMouseEnter={() => mark(c.iri!, true, own())}
                          onMouseLeave={() => mark(c.iri!, false, own())}
                        >
                          <ConstraintContent c={c} />
                          <Show when={c.label}><span class="c-note muted">{c.label}</span></Show>
                          <Show when={u().reasons[c.iri!] === 'not-enforced'}>
                            <span class="cov-not-enforced" title={text('cov.notEnforcedTitle')}>
                              {text('cov.notEnforced')}
                            </span>
                          </Show>
                          <Show when={u().reasons[c.iri!] === 'organisational'}>
                            <span class="cov-organisational muted" title={text('cov.organisationalTitle')}>
                              {text('cov.organisational')}
                            </span>
                          </Show>
                        </li>
                      )}</For>
                    </ul>
                  </div>
                )}</Show>
              </div>
            </Show>
          </div>
        </aside>
      )}</Show>
      <Show when={edgeHint()}>{(pos) => (
        <div class={'ref-edge ' + (pos() === 'above' ? 'edge-top' : 'edge-bottom')} aria-hidden="true">
          <span class="ref-edge-arrow">{pos() === 'above' ? '▲' : '▼'}</span>
        </div>
      )}</Show>
    </>
  );
}
