import { createEffect, createSignal, For, onCleanup, Show } from 'solid-js';
import { sources, endpoint, errors } from '../../stores/corpus.js';

import {
  editSource, lazyLoadedNotice, sourceRows, makeWorkFile, opfsOn, addSourceByAddress,
} from '../../stores/source-management.js';
import type { SourceEdit } from '../../stores/source-management.js';
import { exampleSearchString } from '../../model/default-corpus.js';
import { text } from '../../stores/view.js';
import { safeHref } from '../shared/safe-link.js';
import { SourceActions, EndpointLine } from './source-actions.jsx';
import './sources.css';

export function errorTable(
  errors: readonly { url?: string; name?: string; message: string }[],
): Map<string, string> {
  const byKey = new Map<string, string>();
  for (const f of errors) {
    if (f.name) byKey.set(f.name, f.message);
    if (f.url) byKey.set(f.url, f.message);
  }
  return byKey;
}

export function SourceName(props: { name: string; url?: string }) {

  return (
    <Show when={safeHref(props.url)} fallback={<span class="src-naam">{props.name}</span>}>
      {(u) => <a class="src-naam" href={u()} target="_blank" rel="noopener">{props.name}</a>}
    </Show>
  );
}

export function SrcButton(props: {
  cls: string; label: string; title: string; off?: boolean;
  act: () => void;
}) {
  return (
    <button
      type="button"
      class={props.cls}
      title={props.title}
      aria-label={props.title}
      disabled={props.off || undefined}
      onClick={() => { if (!props.off) props.act(); }}
    >{props.label}</button>
  );
}

export function SourceError(props: { error?: string }) {
  return <Show when={props.error}>{(m) => <span class="src-foutnoot">{' — ' + m()}</span>}</Show>;
}

const [sourcesOpen, setSourcesOpen] = createSignal(false);
export { sourcesOpen, setSourcesOpen };

export function SourcesButton() {
  return (
    <button
      class="btn bronnen-knop"
      id="btn-bronnen"
      type="button"
      aria-controls="bronnen-paneel"
      aria-expanded={sourcesOpen() ? 'true' : 'false'}
      onClick={() => setSourcesOpen(!sourcesOpen())}
    >{text('src.toggle')}</button>
  );
}

function AddSourceField() {
  const [address, setAddress] = createSignal('');

  const [last, setLast] = createSignal<string | null>(null);
  const [duplicate, setDuplicate] = createSignal<string | null>(null);
  const note = () => {
    const d = duplicate();
    if (d) return text('src.alreadyLoaded', { url: d });
    const u = last();
    if (!u) return null;
    const f = errors().find((x) => x.url === u);
    return f ? text('src.addError', { url: u, fout: f.message }) : null;
  };
  const submit = (e: Event) => {
    e.preventDefault();
    const u = address().trim();
    if (!u) return;
    setAddress('');
    const outcome = addSourceByAddress(u);
    setDuplicate(outcome === 'dubbel' ? u : null);
    setLast(outcome === 'toegevoegd' ? u : null);
  };
  return (
    <>
      <form class="bronnen-toevoegform" onSubmit={submit}>
        <input
          type="text"
          class="src-add-url"
          id="src-add-url"
          value={address()}
          placeholder={text('src.placeholder')}
          aria-label={text('src.addLabel')}
          onInput={(e) => setAddress(e.currentTarget.value)}
        />
        <button type="submit" class="btn src-add-ok">{text('src.addButton')}</button>
      </form>
      <Show when={note()}>{(n) => <p class="src-toevoegnoot muted">{n()}</p>}</Show>
    </>
  );
}

export function SourcesPanel(props: {

  editing?: () => boolean;
} = {}) {
  const editing = () => !!props.editing?.();
  const table = () => errorTable(errors());
  const errorFor = (b: SourceEdit) =>
    table().get(b.name) ?? (b.url ? table().get(b.url) : undefined);

  const rows = () => sourceRows().filter((b) => !b.fromSparql && !b.vocab);
  const vocabRows = () => sourceRows().filter((b) => !b.fromSparql && b.vocab);
  const empty = () => !rows().length && !endpoint();

  createEffect(() => {
    const b = typeof document === 'undefined' ? null : document.body;
    if (b) b.classList.toggle('bronnen-open', sourcesOpen());
  });
  onCleanup(() => {
    if (typeof document !== 'undefined') document.body.classList.remove('bronnen-open');
  });

  function closePanel(focusFollows: boolean): void {
    setSourcesOpen(false);
    if (!focusFollows || typeof document === 'undefined') return;
    (document.getElementById('btn-bronnen') as HTMLElement | null)?.focus();
  }

  // Capture, so this layer can consume the Escape before the sidenav sees it.
  // The four exits below are the layers above this one.
  function onKey(e: KeyboardEvent): void {
    if (e.key !== 'Escape' || !sourcesOpen() || typeof document === 'undefined') return;
    const classes = document.body?.classList;
    if (classes?.contains('bronkiezer-open') || classes?.contains('panel-open')) return;
    const a = document.activeElement as HTMLElement | null;
    const tag = String((a && a.tagName) || '').toLowerCase();
    if (tag === 'input' || tag === 'textarea' || a?.isContentEditable) return;
    const panel = document.getElementById('bronnen-paneel');
    if (panel?.querySelector('[aria-haspopup="menu"][aria-expanded="true"]')) return;
    closePanel(!!(panel && a && panel.contains(a)));
    e.preventDefault();
    if (e.stopImmediatePropagation) e.stopImmediatePropagation();
    else e.stopPropagation();
  }
  if (typeof document !== 'undefined' && document.addEventListener) {
    document.addEventListener('keydown', onKey, true);
    onCleanup(() => document.removeEventListener('keydown', onKey, true));
  }

  return (
    <aside
      class="bronnen-paneel"
      id="bronnen-paneel"
      hidden={!sourcesOpen()}
      data-bewerken={editing() ? '1' : undefined}
      aria-labelledby="label-bronnen"
    >
      <div class="bronnen-kop">
        <h2 class="bronnen-label" id="label-bronnen">{text('src.loaded')}</h2>
                <button
          class="bronnen-sluit"
          id="btn-bronnen-sluit"
          type="button"
          title={text('src.close')}
          aria-label={text('src.close')}
          onClick={() => closePanel(true)}
        >✕</button>
      </div>
      <div class="bronnen-body">
                <Show when={editing()}>
          <p class="bronnen-uitleg muted">{text('src.editSourcePanel')}</p>
        </Show>
        <ul class="bronnen-lijst" id="bronnen-lijst" aria-labelledby="label-bronnen">
          <For each={rows()}>{(b) => (
            <li
              class={errorFor(b) ? 'src-error-li' : undefined}
              data-bron={b.name}
              data-modus={b.modus}
              data-graph={b.graph}
            >
              <SourceName name={b.name} url={b.url} />
                            <Show when={b.opfs}>
                <span class="src-lokaal" title={text('src.localHint')}>
                  {' ' + text('src.local')}
                </span>
              </Show>
              {' '}
              <SourceActions source={b} error={errorFor(b)} />
              <SourceError error={errorFor(b)} />
            </li>
          )}</For>
          <EndpointLine />
        </ul>
        {/* Always in the DOM, text only when empty: a live region that first
            appears together with its message is not read out. */}
        <p
          class="bronnen-leeg muted"
          role="status"
          data-leeg={empty() ? '1' : undefined}
        >
          <Show when={empty()}>
            {text('src.noSources')}
            {' '}
                        <a class="src-voorbeelden" href={exampleSearchString()}>{text('src.examples')}</a>
          </Show>
        </p>

                <Show when={lazyLoadedNotice()}>{(m) => (
          <p class="muted src-bijgeladen">{text('src.lazyLoadedShort', { n: m().n })}</p>
        )}</Show>

                <h3 class="bronnen-label bronnen-toevoeg-label" id="label-bron-toevoegen">
          {text('src.addLabel')}
        </h3>
        <AddSourceField />
        <ul class="bronnen-gereedschap" aria-labelledby="label-bron-toevoegen">
          <li class="src-gereedschap">
            <SrcButton
              cls="src-werkbestand"
              label={text('src.workFile')}
              title={opfsOn() ? text('src.workFileHint') : text('src.opfsOff')}
              off={!opfsOn()}
              act={() => void makeWorkFile()}
            />
            {' '}
                        <Show when={editing() && !editSource() && rows().length}>
              <span class="src-geen-bewerkbron">{text('src.noEditSource')}</span>
            </Show>
          </li>
        </ul>

                <Show when={vocabRows().length}>
          <h3 class="bronnen-label bronnen-vocab-label" id="label-vocabulaire">
            {text('src.vocabulary')}
          </h3>
          <ul class="bronnen-lijst bronnen-vocab" aria-labelledby="label-vocabulaire">
            <For each={vocabRows()}>{(b) => (
              <li data-bron={b.name} data-vocab="1" data-modus={b.modus}>
                <SourceName name={b.name} url={b.url} />
                <SourceError error={errorFor(b)} />
              </li>
            )}</For>
          </ul>
          <p class="bronnen-vocab-uitleg muted">{text('src.vocabularyHint')}</p>
        </Show>
      </div>
    </aside>
  );
}
