import { createEffect, createSignal, onCleanup, Show } from 'solid-js';
import { endpoint } from '../../stores/corpus.js';
import {
  editSource, downloadSource, restoreOriginal, makeEditable, makeEndpointEditable,
  opfsOn, updateUrlProposal, lockEndpoint, removeSource,
} from '../../stores/source-management.js';
import type { SourceEdit } from '../../stores/source-management.js';
import { text } from '../../stores/view.js';
import { SrcButton } from './sources.jsx';

export function DownloadMenu(props: { source: SourceEdit }) {
  const [open, setOpen] = createSignal(false);
  let buttonEl: HTMLButtonElement | undefined;
  let wrapEl: HTMLSpanElement | undefined;

  const items = (): HTMLButtonElement[] =>
    [...(wrapEl?.querySelectorAll<HTMLButtonElement>('[role="menuitem"]') ?? [])];

  const close = (back = true) => {
    setOpen(false);
    if (back) buttonEl?.focus();
  };
  const openAt = (which: 'first' | 'last') => {
    setOpen(true);
    const l = items();
    (which === 'first' ? l[0] : l[l.length - 1])?.focus();
  };
  const choose = (format: 'ttl' | 'jsonld') => {
    void downloadSource(props.source, format);
    close();
  };

  createEffect(() => {
    if (!open() || typeof document === 'undefined') return;
    const outside = (e: Event) => {
      if (!wrapEl?.contains(e.target as Node)) setOpen(false);
    };
    document.addEventListener('pointerdown', outside, true);
    onCleanup(() => document.removeEventListener('pointerdown', outside, true));
  });

  return (
    <span
      class="src-downloadmenu"
      ref={wrapEl}

      // `on:keydown` and not `onKeyDown`: Solid delegates to the document, so a
      // delegated stopPropagation comes too late for the Escape layers.
      on:keydown={(e: KeyboardEvent) => {
        if (e.key === 'Escape' && open()) {
          e.preventDefault(); e.stopPropagation(); close(); return;
        }
        const l = items();
        const here = l.indexOf(document.activeElement as HTMLButtonElement);
        if (e.key === 'ArrowDown') {
          e.preventDefault(); e.stopPropagation();
          if (!open()) { openAt('first'); return; }
          l[(here + 1) % l.length]?.focus();
        } else if (e.key === 'ArrowUp') {
          e.preventDefault(); e.stopPropagation();
          if (!open()) { openAt('last'); return; }
          l[(here - 1 + l.length) % l.length]?.focus();
        }
      }}
    >
      <button
        type="button"
        class="src-download"
        ref={buttonEl}
        title={text('src.downloadMenu')}
        aria-label={text('src.downloadMenu')}
        aria-haspopup="menu"
        aria-expanded={open() ? 'true' : 'false'}
        onClick={() => (open() ? close() : openAt('first'))}
      >⤓</button>
      <Show when={open()}>
        <ul class="src-download-menu" role="menu" aria-label={text('src.downloadMenu')}>
          <li role="none">
            <button
              type="button"
              role="menuitem"
              class="src-download-ttl"
              title={text('src.download')}
              onClick={() => choose('ttl')}
            >{text('src.downloadTtlKort')}</button>
          </li>
          <li role="none">
            <button
              type="button"
              role="menuitem"
              class="src-download-jsonld"
              title={text('src.downloadJsonLd')}
              onClick={() => choose('jsonld')}
            >{text('src.downloadJsonLdKort')}</button>
          </li>
        </ul>
      </Show>
    </span>
  );
}

export function refusalReasonKey(source: SourceEdit, error?: string): string | null {
  if (source.modus === 'readwrite' || source.opfs) return null;
  if (!opfsOn()) return 'src.opfsOff';
  if (error) return 'src.lockError';
  return null;
}

export function refusalReason(source: SourceEdit, error?: string): string | null {
  const key = refusalReasonKey(source, error);
  return key ? text(key) : null;
}

// `aria-disabled` and not `disabled`: the reason lives in the tooltip and must
// stay reachable from the keyboard.
function MakeEditableButton(props: { source: SourceEdit; error?: string }) {
  const reason = () => refusalReason(props.source, props.error);
  const title = () => {
    const r = reason();
    if (r) return r;
    return props.source.opfs
      ? text('src.chooseEditSource')
      : `${text('src.chooseEditSource')} — ${text('src.lockWarning')}`;
  };
  return (
    <button
      type="button"
      class="src-edit"
      title={title()}
      aria-label={title()}
      aria-disabled={reason() ? 'true' : undefined}
      onClick={() => {
        if (reason()) return;
        void makeEditable(props.source);
      }}
    >✎</button>
  );
}

export function SourceActions(props: { source: SourceEdit; error?: string }) {
  const editable = () => props.source.modus === 'readwrite';
  return (
    <span class="src-acties">
      <Show when={editable()} fallback={<MakeEditableButton source={props.source} error={props.error} />}>
        <Show when={props.source.url}>
          <SrcButton
            cls="src-revert"
            label="↶"
            title={text('src.unlock')}
            act={() => void restoreOriginal(props.source)}
          />
        </Show>
        <DownloadMenu source={props.source} />
      </Show>
            <SrcButton
        cls="src-remove"
        label="✕"
        title={text('src.remove')}
        act={() => void removeSource(props.source)}
      />
    </span>
  );
}

function UpdateUrlField(props: { ep: string; done: () => void }) {
  const [value, setValue] = createSignal(updateUrlProposal(props.ep));
  return (
    <span class="src-update-veld">
      {' '}
      <input
        type="text"
        class="src-update-url"
        value={value()}
        aria-label={text('src.updateUrl')}
        title={text('src.updateUrl')}
        onInput={(e) => setValue(e.currentTarget.value)}
      />
      {' '}
      <button
        type="button"
        class="src-update-ok"
        onClick={() => {
          const url = value().trim();
          if (!url) return;
          void makeEndpointEditable(url);
          props.done();
        }}
      >{text('src.updateOk')}</button>
    </span>
  );
}

export function EndpointLine() {
  const [urlFieldOpen, setUrlFieldOpen] = createSignal(false);
  const epOn = () => {
    const b = editSource();
    return !!b && b.kind === 'sparql';
  };
  return (
    <Show when={endpoint()}>{(ep) => (
      <li class="muted src-endpoint-li" data-modus={epOn() ? 'readwrite' : 'read'}>
        <span class="src-naam">{ep()}</span>
        <span class="src-endpoint-note">{text('src.endpointNote')}</span>
        <Show when={epOn()}>
          <span class="src-lokaal">
            {' ' + text('src.updateTo', { url: editSource()?.updateUrl ?? '' })}
          </span>
        </Show>
        {' '}
        <span class="src-acties">
          <Show
            when={epOn()}
            fallback={
              <button
                type="button"
                class="src-edit"
                title={text('src.chooseEditSource')}
                aria-label={text('src.chooseEditSource')}
                onClick={() => setUrlFieldOpen(true)}
              >✎</button>
            }
          >
            <SrcButton
              cls="src-revert"
              label="↶"
              title={text('src.stopEditSource')}
              act={() => { void lockEndpoint(); setUrlFieldOpen(false); }}
            />
          </Show>
        </span>
        <Show when={urlFieldOpen() && !epOn()}>
          <UpdateUrlField ep={ep()} done={() => setUrlFieldOpen(false)} />
        </Show>
      </li>
    )}</Show>
  );
}
