import { For, Show, createMemo, createSignal } from 'solid-js';
import type { JSX } from 'solid-js';
import { curie } from '../../model-boundary.js';
import { text } from '../../stores/view.js';
import './constraints.css';

export interface Slot { text: string; desc?: string }

export interface Constraint {
  rowRef?: string | null;
  iri?: string | null;
  label?: string | null;
  comment?: string | null;
  sentence?: string;
  logical?: string | null;
  children?: Constraint[];
  slots?: {
    left: Slot | null;
    operator: Slot | null;
    right: { texts: string[]; descs?: string[]; iris?: (string | null)[] } | null;
  } | null;
  left?: string | null;
  operator?: string | null;
  right?: string[];
  rightOperandReference?: string[];
  unaryOperator?: boolean;
  unknownProps?: { curie: string; values: string[] }[];
  technicalMeasure?: boolean;
  conformsOp?: boolean;
  conformsTo?: string | null;
  organisational?: boolean;
  purposeBinding?: boolean;
}

export const RIGHT_CHIPS_SHOWN = 5;

export const GROUP_COLLAPSE_LEAVES = 10;

const LOGICAL_OPERATORS = ['and', 'andSequence', 'or', 'xone'];

export function logicalHead(op: string): string {
  return LOGICAL_OPERATORS.includes(op) ? text('logicalHead.' + op) : op;
}

export function countLeaves(c: Constraint): number {
  if (!c.children || !c.children.length) return 1;
  return c.children.reduce((n, ch) => n + countLeaves(ch), 0);
}

export function chipSlots(c: Constraint): NonNullable<Constraint['slots']> {
  if (c.slots) return c.slots;
  const rightTexts = [...(c.right || []), ...(c.rightOperandReference || [])];
  return {
    left: c.left ? { text: c.left } : null,
    operator: c.operator ? { text: c.operator } : null,
    right: rightTexts.length ? { texts: rightTexts } : null,
  };
}

function missingTitle(pred: string, unknownProps?: { curie: string; values: string[] }[]): string {
  let txt = text('slot.missingTitle', { pred });
  if (unknownProps && unknownProps.length) {
    txt += text('slot.unknownProps')
      + unknownProps.map((u) => `${u.curie} → ${u.values.join(', ')}`).join('; ') + '.';
  }
  return txt;
}

function MissingChip(props: {
  key: string; pred: string; unknownProps?: { curie: string; values: string[] }[];
}): JSX.Element {
  const candidate = () => (props.unknownProps || []).find((u) => u && u.curie);
  return (
    <span class="c-slot missing" title={missingTitle(props.pred, props.unknownProps)}>
      <span class="c-warn" aria-hidden="true">
        <svg viewBox="0 0 16 16" width="11" height="11">
          <path d="M8 1.5 15 14H1z" fill="#e3b341" stroke="#a97a10" stroke-width="1" />
          <rect x="7.3" y="6" width="1.4" height="4" rx=".7" fill="#5c4304" />
          <circle cx="8" cy="11.8" r=".9" fill="#5c4304" />
        </svg>
      </span>
      <span>{candidate() ? candidate()!.curie : text(props.key)}</span>
    </span>
  );
}

export function Chip(props: {
  cls: string; text: string; desc?: string;
  chevron?: JSX.Element | null;
}): JSX.Element {
  return (
    <span
      class={'c-slot ' + props.cls + (props.chevron ? ' vouwkop' : '')}
      data-desc={props.desc || undefined}
    >
      <Show when={props.chevron} fallback={props.text}>
        <span class="c-slot-tekst">{props.text}</span>
      </Show>
      {props.chevron}
    </span>
  );
}

// A real space character: without it a copied chip row pastes as one glued word.
export function ChipSpace(): JSX.Element {
  return <span class="c-ruimte"> </span>;
}

export function foldValue(
  c: Constraint, covers: (iri: string) => boolean,
): string | null {
  const iris = chipSlots(c).right?.iris || [];
  for (let i = 0; i < iris.length && i < RIGHT_CHIPS_SHOWN; i += 1) {
    const iri = iris[i];
    if (iri && covers(iri)) return iri;
  }
  return null;
}

export function ConstraintChips(props: {
  c: Constraint;
  foldIri?: string | null;
  chevron?: JSX.Element | null;
}): JSX.Element {
  const [all, setAll] = createSignal(false);
  const slots = createMemo(() => chipSlots(props.c));
  const texts = () => slots().right?.texts || [];
  const descs = () => slots().right?.descs || [];
  const iris = () => slots().right?.iris || [];
  const foldIndex = () => (props.foldIri ? iris().indexOf(props.foldIri) : -1);
  const tooMany = () => texts().length > RIGHT_CHIPS_SHOWN + 1;
  const shown = () => (tooMany() && !all()
    ? texts().slice(0, RIGHT_CHIPS_SHOWN) : texts());
  return (
    <span class="c-chips">
      <Show
        when={slots().left}
        fallback={(
          <MissingChip
            key="slot.leftMissing" pred="odrl:leftOperand"
            unknownProps={props.c.unknownProps}
          />
        )}
      >{(s) => <Chip cls="left" text={s().text} desc={s().desc} />}</Show>
      <ChipSpace />
      <Show
        when={slots().operator}
        fallback={(
          <MissingChip
            key="slot.operatorMissing" pred="odrl:operator"
            unknownProps={props.c.unknownProps}
          />
        )}
      >{(s) => <Chip cls="op" text={s().text} desc={s().desc} />}</Show>
      <ChipSpace />
      <Show
        when={slots().right}
        fallback={(
          <Show when={!props.c.unaryOperator}>
            <MissingChip
              key="slot.valueMissing" pred="odrl:rightOperand"
              unknownProps={props.c.unknownProps}
            />
          </Show>
        )}
      >
        <For each={shown()}>{(t, i) => (
          <>
            <Show when={i() > 0}><ChipSpace /></Show>
            <Chip
              cls="right" text={t} desc={descs()[i()]}
              chevron={i() === foldIndex() ? props.chevron : null}
            />
          </>
        )}</For>
        <Show when={tooMany()}>
          <ChipSpace />
          <button
            type="button" class="c-slot more c-meer"
            aria-expanded={all() ? 'true' : 'false'}
            onClick={() => setAll((v) => !v)}
          >
            {all() ? text('constraint.showFewer')
              : text('constraint.showAll', { n: texts().length })}
          </button>
        </Show>
      </Show>
    </span>
  );
}

export function Note(props: { c: Constraint }): JSX.Element {
  return (
    <Show when={props.c.label}>{(l) => (
      <>
        <ChipSpace />
        <span class="c-note muted">{l()}</span>
        <ChipSpace />
      </>
    )}</Show>
  );
}

export function titleOf(c: Constraint): string | undefined {
  return [c.label, c.comment].filter(Boolean).join(' — ') || undefined;
}

export function ConstraintNode(props: { c: Constraint; depth?: number }): JSX.Element {
  const depth = () => props.depth || 0;
  const isGroup = () => !!(props.c.logical && props.c.children && props.c.children.length);
  const groupLabel = () => text('constraint.foldSummary', {
    label: props.c.label || text('constraint.compound'),
    head: logicalHead(props.c.logical as string),
    n: countLeaves(props.c),
  });
  return (
    <Show
      when={isGroup()}
      fallback={(
        <span class="c-leaf" title={titleOf(props.c)}>
          <ConstraintChips c={props.c} />
          <Note c={props.c} />
        </span>
      )}
    >
      <div
        class="c-group" role="group" aria-label={groupLabel()}
        data-diepte={String(depth())} title={titleOf(props.c)}
      >
        <div class="c-group-head">
          <span class="c-slot op">{logicalHead(props.c.logical as string)}</span>
          <span class="c-group-telling muted">
            {text('constraint.groupCount', { n: countLeaves(props.c) })}
          </span>
          <Note c={props.c} />
        </div>
        <ul class="clean c-group-items" data-diepte={String(depth() + 1)}>
          <For each={props.c.children}>{(ch) => (
            <li class="c-group-item"><ConstraintNode c={ch} depth={depth() + 1} /></li>
          )}</For>
        </ul>
      </div>
    </Show>
  );
}

export function ConstraintContent(props: { c: Constraint }): JSX.Element {
  const isGroup = () => !!(props.c.logical && props.c.children && props.c.children.length);
  return (
    <Show
      when={isGroup()}
      fallback={(
        <Show
          when={props.c.slots}
          fallback={<span class="sentence">{props.c.sentence || curie(props.c.iri || '')}</span>}
        >
          <ConstraintChips c={props.c} />
        </Show>
      )}
    >
      <ConstraintNode c={{ ...props.c, label: null }} />
    </Show>
  );
}
